"""Original Lithuanian monthly framing and concise, source-backed focus notes."""
MONTH_NOTES=[
('Atmintis ir metų pradžia','Sausį Naujųjų metų diena yra vienintelė DK 123 straipsnio šventinė diena. Sausio 1-ąją taip pat minima Lietuvos vėliavos diena, o sausio 13-oji skirta laisvės gynėjų atminimui.',
 [('stat-new-year','Viena data, du statusai','Sausio 1-oji yra Naujųjų metų šventinė diena ir Lietuvos vėliavos atmintina diena. Kalendoriaus langelyje abu įrašai išlieka atskiri; tai nesukuria dviejų laisvų dienų.'),('comm-003','Atmintis nėra papildoma nedarbo diena','Sausio 13-oji minima trečiadienį. Ji įtraukta į Atmintinų dienų įstatymą, tačiau nėra DK 123 straipsnio šventinė diena.'),('three-kings','Trijų Karalių papročiai','Sausio 6-oji tradiciniame kalendoriuje užbaigia tarpušventį. Vietos bendruomenių vaikštynės ir jų laikas gali skirtis; būsimos renginių programos čia nežadame.')],
 'Ar sausio 13-ąją visiems suteikiama laisva diena?','Ne. Tai atmintina diena. Vienintelis sausio įrašas DK 123 straipsnio švenčių sąraše yra Naujųjų metų diena.'),
('Valstybės atkūrimas ir žiemos palydos','2027 m. vasario 16-oji bus antradienis. Užgavėnės šiemet patenka į vasario 9-ąją; tą pačią dieną įstatymas taip pat numato Baltijos šalių energetinės nepriklausomybės minėjimą.',
 [('stat-restoration','Vasario 16-oji – šventinė diena','Lietuvos valstybės atkūrimo dieną paprastai nedirbama pagal DK 123 straipsnį. Jai skirtą istorinį paaiškinimą rasite atskirame šventės puslapyje.'),('uzgavenes','Kodėl Užgavėnės vasario 9-ąją?','Pagal vakarietiškųjų Velykų datą jos skaičiuojamos likus 47 dienoms iki kovo 28-osios. Tai tradicinė žiemos palydų data, nesuteikianti papildomos nedarbo dienos.'),('mother-language','Kalbų įvairovei skirta diena','UNESCO gimtosios kalbos dieną mini vasario 21-ąją. Tai tarptautinė kalendorinė data; 2027 m. renginių temos ir programos iš anksto nepriskiriamos.')],
 'Ar Užgavėnės visada vasario 9-ąją?','Ne. Jų data priklauso nuo vakarietiškųjų Velykų. Vasario 9-oji yra būtent 2027 m. data.'),
('Nepriklausomybė, verbos ir Velykos','Kovą laukia trys šventinės dienos: Kovo 11-oji bei Velykos kovo 28 ir 29 d. Verbų sekmadienis bus kovo 21-ąją, o Knygnešio diena – kovo 16-ąją.',
 [('stat-independence','Kovo 11-oji – ketvirtadienį','Lietuvos nepriklausomybės atkūrimo diena yra šventinė diena. Jos nereikia painioti su vasario 16-ąją minima valstybės atkūrimo diena.'),('stat-easter','Velykos šiemet – dar kovą','Vakarietiškosios Velykos bus kovo 28 d., sekmadienį; antroji diena – kovo 29 d., pirmadienį. Abi dienos priklauso DK 123 straipsnio švenčių sąrašui.'),('palms','Verbos ir Kaziuko mugė – skirtingi orientyrai','Verbų sekmadienis skaičiuojamas savaite prieš Velykas. Kovo 4-oji yra šv. Kazimiero diena, bet ji pati nenustato visų Kaziuko mugės renginių datų.')],
 'Kodėl kovo 29 d. rodomi du įrašai?','Tą pirmadienį sutampa Antroji Velykų diena ir Lietuvos įstojimo į NATO atmintina diena. Nedarbo dienos pagrindas yra Velykos.'),
('Pavasario tęsinys ir knygos','Balandį DK 123 straipsnio šventinių dienų nėra. Atvelykis bus balandžio 4-ąją, o mėnesio antroje pusėje atskirai pažymėtos Motinos Žemės ir knygos bei autorių teisių dienos.',
 [('atvelykis','Atvelykis – balandžio 4 d.','Pirmasis sekmadienis po Velykų dar vadinamas Vaikų Velykėlėmis. Kultūros šaltiniai jį sieja su žaidimais ir margučių ridenimu; tai nėra papildoma DK šventinė diena.'),('earth','Dvi skirtingos Žemės dienos','Balandžio 22-oji yra Jungtinių Tautų Motinos Žemės diena. Lietuvos Atmintinų dienų įstatyme įrašyta kovo 20-osios Žemės diena čia neperkeliama į kitą mėnesį.'),('world-book','Skaitymui ir autorių teisėms','UNESCO Pasaulinę knygos ir autorių teisių dieną mini balandžio 23-ąją. Ši tarptautinė data atskirta nuo gegužės 7-osios lietuviškos spaudos ir kalbos dienos.')],
 'Ar balandžio 15-oji tebėra Kultūros diena?','Galiojančioje Atmintinų dienų įstatymo redakcijoje balandžio 15-oji yra Pasaulinė meno diena. Kultūros diena įrašyta rugsėjo 22-ąją.'),
('Šeima, kalba ir bendrystė','Gegužės 1-oji bus šeštadienis, Motinos diena – gegužės 2 d., sekmadienis. Vaiko diena švenčiama trečiąjį gegužės penktadienį, todėl 2027 m. jos data yra gegužės 21-oji.',
 [('stat-mothers','Motinos diena – pirmąjį sekmadienį','2027 m. tai gegužės 2-oji. Ji yra DK 123 straipsnio šventinė diena; jos sutapimas su sekmadieniu savaime neperkelia šventės į pirmadienį.'),('comm-037','Lietuviško žodžio diena','Gegužės 7-oji skirta spaudos atgavimui, kalbai ir knygai. Tai Lietuvos įstatyme nustatyta atmintina diena, atskira nuo UNESCO balandžio knygos dienos.'),('comm-045','Vaiko diena – gegužės 21 d.','Taikoma trečiojo penktadienio taisyklė. Tą pačią dieną minima ir Lietuvos tautinių bendrijų diena, todėl langelyje matomi du atskiri įrašai.')],
 'Ar gegužės šventės perkeliamos į pirmadienį?','Ne automatiškai. 2027 m. gegužės 1 ir 2 d. sutampa su savaitgaliu; planuodami darbą vertinkite savo grafiką ir taikomas darbo teisės normas.'),
('Vasaros tradicijos ir istorinė atmintis','Tėvo diena 2027 m. bus birželio 6-ąją, o Rasos ir Joninių diena – birželio 24-ąją. Birželio 14 ir 15 d. atminties datos žymimos atskirai nuo šventinių nedarbo dienų.',
 [('stat-fathers','Tėvo diena – birželio 6 d.','Data nustatoma pirmąjį birželio sekmadienį. Tai šventinė diena pagal Darbo kodeksą, o ne vien kultūrinis minėjimas.'),('comm-050','Birželio 14-oji: kelios atminimo temos','Įstatyme ši data siejama su Gedulo ir vilties diena, palaimintuoju Teofiliumi Matulioniu ir kraujo donoryste. Istorinis minėjimas savaime nesuteikia nedarbo dienos.'),('stat-jonines','Rasos ir Joninės – birželio 24 d.','Šventinė diena bus ketvirtadienį. Vainikai, žolynai ir laužai yra kultūros šaltiniuose aptariami papročiai; astronominė saulėgrįža yra atskiras momentas.')],
 'Ar Joninės ir vasaros saulėgrįža yra tas pats?','Ne. Birželio 24-oji yra įstatymo nustatyta Rasos ir Joninių diena. Saulėgrįžos astronominį momentą rasite astronominiame kalendoriuje.'),
('Valstybingumas ir vasaros bendruomenės','Liepos 6-oji 2027 m. bus antradienis. Mėnesį taip pat žymimos kilnojamosios Giminių, Globėjų ir Jūros bei Žvejų dienos, kurių datos apskaičiuotos pagal įstatymo savaitės taisykles.',
 [('stat-statehood','Liepos 6-oji – valstybės šventė','Oficialus pavadinimas sieja Lietuvos karaliaus Mindaugo karūnavimą ir Tautišką giesmę. Iliustracijos karūna yra simbolinė, ne istorinio radinio rekonstrukcija.'),('comm-054','Globėjų diena – liepos 4 d.','Pirmasis liepos sekmadienis skirtas globėjams. Dieną prieš ją, liepos 3-iąją, pagal pirmojo šeštadienio taisyklę minima Giminių diena.'),('comm-059','Jūros ir Žvejų diena – liepos 25 d.','Įstatymas nurodo paskutinį liepos sekmadienį. Tai kalendorinė data; konkrečių miestų švenčių programos ir renginių savaitgaliai tikrinami pas organizatorius.')],
 'Ar Jūros diena patvirtina visos miesto šventės programą?','Ne. Įstatymo data ir konkretaus organizatoriaus renginių programa yra skirtingi dalykai.'),
('Žolynai ir laisvės kelias','Žolinė 2027 m. bus rugpjūčio 15-ąją, sekmadienį. Rugpjūčio 23-oji sieja totalitarinių režimų aukų atminimą su Baltijos keliu, o rugpjūčio 31-oji yra Laisvės diena.',
 [('stat-assumption','Žolinė – rugpjūčio 15 d.','Šventė turi ir katalikišką pavadinimą – Švč. Mergelės Marijos ėmimo į dangų diena. Žolynų puokštės iliustracija primena tradiciją, bet nėra visiems privalomas papročių sąrašas.'),('comm-065','Baltijos kelio ir aukų atminimo diena','Rugpjūčio 23 d. bus pirmadienis. Šios atmintinos dienos nereikia laikyti papildoma šventine nedarbo diena.'),('comm-066','Laisvės diena – rugpjūčio 31 d.','Ji yra atskiras įstatymo įrašas mėnesio pabaigoje. Šaltiniai ir teisinė kategorija pateikti prie datos.')],
 'Ar po sekmadienio Žolinės pirmadienis automatiškai laisvas?','Ne. Šventė savaime neperkeliama į pirmadienį; konkretus poilsis priklauso nuo darbo grafiko ir taikomų susitarimų.'),
('Mokslas, kultūra ir pagarbi atmintis','Rugsėjį DK 123 straipsnio šventinių dienų nėra. Mokslo ir žinių diena bus trečiadienį; rugsėjo 22-oji apima baltų vienybę ir kultūrą, o rugsėjo 23-ioji turi kelis aiškiai atskirtus minėjimus.',
 [('comm-067','Mokslo ir žinių diena – rugsėjo 1 d.','Tai atmintina diena. Šis įrašas pats nesuteikia visiems laisvos dienos ir nenustato konkrečios mokyklos mokslo metų programos.'),('comm-073','Baltų vienybė ir kultūra – rugsėjo 22 d.','Abi temos įrašytos į tą pačią galiojančio įstatymo datą. Jos nepainiojamos su astronominio rudens pradžios momentu.'),('comm-074','Rugsėjo 23-ioji – atmintis ir įtrauktis','Įstatyme įvardijamas Lietuvos žydų genocido atminimas, gestų kalbos ir ekologija. Bendras datos langelis nesuplaka šių skirtingų temų į vieną renginį.')],
 'Ar rugsėjo 1-oji yra bendroji nedarbo diena?','Ne. Ji neįtraukta į DK 123 straipsnio švenčių dienų sąrašą. Individualios darbuotojų garantijos vertinamos atskirai.'),
('Mokytojai, derlius ir Konstitucija','Spalį nėra DK 123 straipsnio šventinių dienų. Mokytojų diena bus spalio 5-ąją, Derliaus diena pagal antrojo šeštadienio taisyklę – spalio 9-ąją, Konstitucijos diena – spalio 25-ąją.',
 [('comm-080','Mokytojų diena – spalio 5 d.','Atmintina diena bus antradienį. Ji skirta mokytojų darbui pažymėti, tačiau nesukuria bendros papildomos nedarbo dienos.'),('comm-082','Derliaus diena – spalio 9 d.','Įstatyme ji nustatyta antrąjį spalio šeštadienį. Vietos bendruomenių derliaus renginių datos gali būti kitokios.'),('comm-086','Konstitucijos diena – spalio 25 d.','Atmintina diena bus pirmadienį. Iliustracijos dokumentų tomas yra simbolinis; jis neatvaizduoja tariamai autentiško istorinio dokumento.')],
 'Ar spalio 25-ąją paprastai nedirbama?','Konstitucijos diena yra atmintina diena. Ji nėra atskira DK 123 straipsnio šventinė nedarbo diena.'),
('Atminimas ir vėlyvo rudens tyla','Lapkričio 1 ir 2 d. yra dvi atskiros šventinės dienos – pirmadienis ir antradienis. Visų Šventųjų diena ir Vėlinės turi skirtingus pavadinimus bei reikšmes.',
 [('stat-all-saints','Visų Šventųjų diena – lapkričio 1 d.','Ši diena skirta šventiesiems ir atskirta nuo lapkričio 2-osios mirusiųjų atminimo. Abi datos įtrauktos į Darbo kodekso švenčių sąrašą.'),('stat-all-souls','Vėlinės – lapkričio 2 d.','Mirusiųjų atminimo diena bus antradienį. Kultūros šaltiniai aptaria kapų lankymą ir žvakių šviesą; iliustracija nėra konkrečių kapinių dokumentinė nuotrauka.'),('comm-095','Lietuvos kariuomenės diena – lapkričio 23 d.','Tai atmintina diena, taip pat patenkanti į antradienį. Jos teisinis statusas skiriasi nuo mėnesio pradžios šventinių dienų.')],
 'Ar Visų Šventųjų diena ir Vėlinės yra viena šventė?','Ne. Lapkričio 1-oji ir 2-oji yra atskiros kalendoriaus ir Darbo kodekso šventinės dienos.'),
('Žmogaus teisės ir žiemos šventės','2027 m. Kūčios bus penktadienį, o Kalėdų dienos – šeštadienį ir sekmadienį. Gruodžio 10-oji, Žmogaus teisių diena, yra atmintina data ir papildomos nedarbo dienos nesuteikia.',
 [('stat-christmas-eve','Kūčios – gruodžio 24 d.','Kūčių diena įtraukta į Darbo kodekso švenčių sąrašą. Lino, kūčiukų ir šiaudinių dirbinių iliustracija primena kultūrinį kontekstą, o ne vienintelį visoms šeimoms bendrą stalą.'),('stat-christmas','Kalėdos – gruodžio 25 ir 26 d.','2027 m. abi Kalėdų dienos sutampa su savaitgaliu. Jos automatiškai neperkeliamos į kitą pirmadienį.'),('comm-100','Žmogaus teisių diena – gruodžio 10 d.','Ši atmintina diena bus penktadienį. Jai taikoma atmintinos dienos kategorija; ji nėra papildoma DK 123 straipsnio šventinė diena.')],
 'Kiek gruodį yra šventinių dienų?','Trys kalendorinės datos: gruodžio 24, 25 ir 26 d. Tai nesuteikia trijų papildomų darbo savaitės poilsio dienų, kai šventės sutampa su savaitgaliu.')
]
